theme.css:
/* ==== INTERFACE ====
   材质   统计算法工作台：冷石白基底承托深岩墨蓝框架，以聚焦琥珀金标定集成收敛与最终强分类器
   token  --bg #F3F6F9           冷石白背景｜全局底色
   token  --surface #FFFFFF      纯白工作台面｜卡片底、图表视窗底
   token  --text #0E1726         深岩墨蓝｜页面大标题、正文成句、轴线主体
   token  --muted #616E7C        冷钢中灰｜刻度、说明标签、次级辅助线（对比度5.2:1）
   token  --border #CBD5E1       冷铝灰边线｜视窗分界、面板外廓
   token  --accent #C2410C       聚焦琥珀橙｜强分类器综合输出、关键操作点、收敛极值
   token  --model-a #1D4ED8      主模型色（矢车菊蓝）｜弱学习器A、Bagging采样集、负类分布
   token  --model-b #0F766E      辅助模型色（冷杉青）｜弱学习器B、残差补正方向、正类分布
   token  --weight-fill #EA580C   权重高亮色｜样本重加权标记、难分类点分布
   token  --fs-h1 34px           大讲标题
   token  --fs-h2 22px           板块与阶段标题
   token  --fs-lead 19px         导语成句
   token  --fs-body 18px         算法机制推导、正文叙述
   token  --fs-sec 16px          次级图解、参数说明、批注
   token  --fs-label 15px        控件标签、图例、状态项
   token  --fs-tick 13px         坐标轴刻度、超参数标尺数字
   token  --font-sans            "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", -apple-system, sans-serif
   token  --font-mono            "JetBrains Mono", "SF Mono", Menlo, Consolas, monospace
   版心   1488×844               #stage 已含 padding
   版式   .stage-main            主视窗占满剩余纵向空间
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;
  --bg: #F3F6F9;
  --surface: #FFFFFF;
  --text: #0E1726;
  --muted: #616E7C;
  --border: #CBD5E1;
  --accent: #C2410C;
  --model-a: #1D4ED8;
  --model-b: #0F766E;
  --weight-fill: #EA580C;
  --focus: #C2410C;
  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;
  --font-sans: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", -apple-system, sans-serif;
  --font-mono: "JetBrains Mono", "SF Mono", Menlo, Consolas, monospace;
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  box-sizing: border-box;
}

.stage-main {
  flex: 1;
  display: flex;
  min-height: 0;
  width: 100%;
}

svg .bar, svg .cell, svg .box {
  width: auto;
  height: auto;
}
